<section class="vc-workflow-intro compact single-task" aria-labelledby="store-intro-title">
  <div class="vc-workflow-icon"><i class="fa-solid fa-store"></i></div>
  <div><span class="vc-section-kicker">YOUR STOREFRONT</span><h2 id="store-intro-title">Help customers understand who you are</h2><p>Keep your public store name, story and support contact accurate and current.</p></div>
</section>
<section class="vc-page-actions"><div><span class="vc-status info" id="vs-status">Loading your store…</span></div></section>
<section class="vc-card vc-focused-form">
  <div class="vc-card-head"><div><h2>Public store profile</h2><span class="vc-help">Shown to customers after approval</span></div></div>
  <form class="vc-card-body vc-form-stack" id="vs-store">
    <div class="vc-field"><label>Store Name</label><input class="vc-input" name="store_name" required minlength="2" maxlength="160" placeholder="e.g., Soil Craft"><small class="vc-help">Use the customer-facing name printed on your products or packaging.</small></div>
    <div class="vc-field"><label>Tagline</label><input class="vc-input" name="tagline" maxlength="180" placeholder="e.g., Handmade pottery rooted in local tradition"><small class="vc-help">Write one short, factual sentence describing your craft or speciality.</small></div>
    <div class="vc-field"><label>Store Description</label><textarea class="vc-textarea" name="description" required minlength="100" maxlength="3000" rows="7" placeholder="Tell customers who makes your products, where they are made, the materials used, and what makes the craft special."></textarea><small class="vc-help">Describe your makers, craft or products accurately. Do not add unsupported impact claims.</small></div>
    <div class="vc-field"><label>Support Email</label><input class="vc-input" name="support_email" type="email" required maxlength="190" placeholder="e.g., support@soilcraft.in"><small class="vc-help">Use an inbox you check regularly for customer questions.</small></div>
    <div class="vc-field"><label>Support Mobile</label><input class="vc-input" name="support_mobile" type="tel" inputmode="numeric" required pattern="[6-9][0-9]{9}" maxlength="10" placeholder="e.g., 9876543210"><small class="vc-help">Enter a 10-digit Indian mobile number used for store support.</small></div>
    <div class="vc-field"><label>Video URL (Optional)</label><input class="vc-input" name="video_url" type="url" maxlength="500" placeholder="e.g., https://youtube.com/watch?v=..."></div>
    <label class="vo-inline-check"><input type="checkbox" name="is_public"><span>Allow my approved store profile to appear publicly</span></label>
    <p class="vc-help">Publishing still depends on product approval and platform checks. Identity and payout details are managed separately.</p>
    <div class="vc-form-actions"><span class="vc-save-confirmation" data-save-confirmation role="status" hidden></span><button class="vc-btn primary" type="submit"><i class="fa-solid fa-floppy-disk"></i> Save store profile</button></div>
  </form>
</section>
<section class="vc-card vc-focused-form mt-3"><div class="vc-card-head"><h2>Customer-facing policies</h2><a class="vc-btn small" href="/conscious/partner/account">Verification details</a></div><div class="vc-card-body" id="vs-policies">Loading…</div></section>
